(5887691, 857515, 83313, '<td valign="top">Overall, I like this, the only thing holding it back a little is the overly bright highlights which dont show off the detail. I''m a detail freak. Your mileage may vary.</td>', 'Overall, I like this, the only thing holding it back a little is the overly bright highlights which dont show off the detail. I''m a detail freak. Your mileage may vary.', '2010-03-03 00:31:09.000000', NULL, 1),
(5887699, 858034, 83313, '<td valign="top">A bit of overkill? I''ll consider myself warned!</td>', 'A bit of overkill? I''ll consider myself warned!', '2010-03-03 00:32:20.000000', NULL, 1),
(5887706, 858088, 83313, '<td valign="top">A bit on the flat side, I''m afraid. Could use some adjustments (levels, curves, contrast, sharpening, etc.) to give it some pop, but it has potential.</td>', 'A bit on the flat side, I''m afraid. Could use some adjustments (levels, curves, contrast, sharpening, etc.) to give it some pop, but it has potential.', '2010-03-03 00:33:54.000000', NULL, 1),
(5887713, 857521, 83313, '<td valign="top">The sepia works well for this, which I find surprising. I don''t usually like sepia tones with such modern subjects.</td>', 'The sepia works well for this, which I find surprising. I don''t usually like sepia tones with such modern subjects.', '2010-03-03 00:34:59.000000', NULL, 1),
(5887715, 858063, 83313, '<td valign="top">Makes a neat abstract. What is this, a fountain?</td>', 'Makes a neat abstract. What is this, a fountain?', '2010-03-03 00:35:45.000000', NULL, 1),
