(5891948, 858010, 109227, '<td valign="top">This one made me smile and that''s worth a 9</td>', 'This one made me smile and that''s worth a 9', '2010-03-05 20:32:05.000000', NULL, 1),
(5891950, 857784, 109227, '<td valign="top">Wish I was there! Very serene.</td>', 'Wish I was there! Very serene.', '2010-03-05 20:33:11.000000', NULL, 1),
