(5898176, 858132, 114259, '<td valign="top"><b>dman22:</b> Yes, they were all house balls. Where I work at (Real Networks in Seattle, WA) there used to be a full bowling ally on the lower floor. When they moved in they kept two lanes, a lot of the bowling balls and shoes.<br/> <br/><b>neophyte:</b> Thanks. I was hoping that all of the parallel lines would help.<br/> <br/><b>Luci11e:</b> I was unaware of how much editing I could do before it became too much. I erred on the side of caution.<br/> <br/><b>LydiaToo:</b> That was a horribly difficult shot. I had to have my tripod do an impression of a yoga master to pull that off. Note to self, I really need to carry a counterbalance.<br/> <br/><b>Yo-Spiff:</b> As I mentioned to neophyte above I didn\''t know what I could do.<br/> <br/>Thank you all for your feedback. I was expecting to get a whopping three in this challenge.<br/> <br/>Taking your suggestions to heart I decided to do some more work on it. I posted it on my flickr account but am prohibited from posting a URL as I am not a full member.<br/> <br/>I''ll do better next time because of all of you.<br/><br/><i>Message edited by author 2010-03-10 09:15:32.</i></td>', 'dman22: Yes, they were all house balls. Where I work at (Real Networks in Seattle, WA) there used to be a full bowling ally on the lower floor. When they moved in they kept two lanes, a lot of the bowling balls and shoes. neophyte: Thanks. I was hoping that all of the parallel lines would help. Luci11e: I was unaware of how much editing I could do before it became too much. I erred on the side of caution. LydiaToo: That was a horribly difficult shot. I had to have my tripod do an impression of a yoga master to pull that off. Note to self, I really need to carry a counterbalance. Yo-Spiff: As I mentioned to neophyte above I didn\''t know what I could do. Thank you all for your feedback. I was expecting to get a whopping three in this challenge. Taking your suggestions to heart I decided to do some more work on it. I posted it on my flickr account but am prohibited from posting a URL as I am not a full member. I''ll do better next time because of all of you.', '2010-03-10 07:41:03.000000', '2010-03-10 09:15:32.000000', 0),
(5898244, 857521, 27608, '<td valign="top">Cool shot!</td>', 'Cool shot!', '2010-03-10 08:28:25.000000', NULL, 0),
(5898247, 857521, 79720, '<td valign="top">Nicely done! And how weird is this...not 24 hours ago, I was <a href="//maps.google.com/maps?f=q&amp;source=s_q&amp;hl=en&amp;geocode=&amp;q=One+London+Place,+London,+Ontario&amp;sll=37.0625,-95.677068&amp;sspn=49.223579,79.013672&amp;ie=UTF8&amp;hq=One+London+Place,&amp;hnear=London,+ON,+Canada&amp;t=h&amp;z=16&amp;layer=c&amp;cbll=42.985916,-81.246897&amp;panoid=kKru7Z19X-N2U6PkLyatVA&amp;cbp=12,142.02,,0,-15.02" rel="nofollow" target="_blank">Google street viewing</a> this building, and I had no idea why.</td>', 'Nicely done! And how weird is this...not 24 hours ago, I was Google street viewing this building, and I had no idea why.', '2010-03-10 08:31:05.000000', NULL, 0),
(5898292, 857911, 111123, '<td valign="top">I like the lines, but I wasn''t sure what it was at first until I looked at the comments you made about the picture. It is a cool shot!</td>', 'I like the lines, but I wasn''t sure what it was at first until I looked at the comments you made about the picture. It is a cool shot!', '2010-03-10 09:04:08.000000', NULL, 0),
(5898296, 856916, 111123, '<td valign="top">Cool lines &amp; it is an interesting picture. The color of the rocks look nice with the white sand! Good job!</td>', 'Cool lines & it is an interesting picture. The color of the rocks look nice with the white sand! Good job!', '2010-03-10 09:08:13.000000', NULL, 0),
(5898321, 858056, 64844, '<td valign="top">Good job with the bright light here! I love those long morning shadows!</td>', 'Good job with the bright light here! I love those long morning shadows!', '2010-03-10 09:30:27.000000', NULL, 0),
(5898336, 857772, 2861, '<td valign="top">Many thanks for you votes. Yo-spiff- you are absolutely right. I had another go at this and came to the conclusion that my critical faculties went AWOL at some stage during this. I don''t even know how I mahaged to generate the artefacts.</td>', 'Many thanks for you votes. Yo-spiff- you are absolutely right. I had another go at this and came to the conclusion that my critical faculties went AWOL at some stage during this. I don''t even know how I mahaged to generate the artefacts.', '2010-03-10 09:49:02.000000', NULL, 0),
(5898378, 857521, 98022, '<td valign="top">Great image and colors. This was my top choice of the challenge. Congrats on the blue!<br/></td>', 'Great image and colors. This was my top choice of the challenge. Congrats on the blue!', '2010-03-10 10:26:51.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5898382, 857898, 98022, '<td valign="top">Awesome shot. Very creative title - fits perfectly. Congrats on the red!</td>', 'Awesome shot. Very creative title - fits perfectly. Congrats on the red!', '2010-03-10 10:28:43.000000', NULL, 0),
(5898387, 858212, 98022, '<td valign="top">Congrats on the yellow Raj. Great details here.</td>', 'Congrats on the yellow Raj. Great details here.', '2010-03-10 10:30:21.000000', NULL, 0),
(5898524, 857521, 105278, '<td valign="top">Nice, Congrats</td>', 'Nice, Congrats', '2010-03-10 12:25:47.000000', NULL, 0),
(5898584, 857023, 18799, '<td valign="top">Greetings from the Critique Club...<br/> <br/>I''m probably not the best one to critique this image because I am one of the apparent minority that really likes this shot.  In fact, when I first opened it up I though I was going to be critiquing one of the top shots, but was quite shocked when I scrolled down and saw how it did!<br/> <br/>To me, this meets the challenge perfectly. I don''t get how people missed the parallel lines in this image???  I like the slight angle to it, and the composition of where the people are placed in the image.  I actually think it would have been a good entry in the fine art challenge.<br/> <br/>Really my only negative is the hot spot in the foreground.<br/> <br/>If I had voted in this challege I would have given this an 8 or maybe a 9 depending on my mood at the time.<br/> <br/>Keep experimenting.<br/><br/><i>Message edited by author 2010-03-10 14:28:23.</i></td>', 'Greetings from the Critique Club... I''m probably not the best one to critique this image because I am one of the apparent minority that really likes this shot.  In fact, when I first opened it up I though I was going to be critiquing one of the top shots, but was quite shocked when I scrolled down and saw how it did! To me, this meets the challenge perfectly. I don''t get how people missed the parallel lines in this image???  I like the slight angle to it, and the composition of where the people are placed in the image.  I actually think it would have been a good entry in the fine art challenge. Really my only negative is the hot spot in the foreground. If I had voted in this challege I would have given this an 8 or maybe a 9 depending on my mood at the time. Keep experimenting.', '2010-03-10 12:59:46.000000', '2010-03-10 14:28:23.000000', 0),
(5898590, 857081, 30982, '<td valign="top">The individual stories here are very good.  There''s a glaring inconsistency in the tableau - that bike is a very nice bike.  Makes you wonder how it got there, to whom it belongs, and why it is still there.  The processing is OK for this scene, though some may feel it too "slick" for a street scene (as in too Topaz''d, HDR''d, whatever).  Great variety of textures, good light.  All in all it works quite well for me.  You''ll note that your commenter average is VERY high - you hit a target audience, it seems.  Some days that is far better than mass appeal in my opinion.  I suspect from a DPC perspective, this didn''t have "in your face" enough parallel lines to truly meet the chalenge for some people.  I didn''t vote this challenge, but this is definitely right up my alley, so to speak.</td>', 'The individual stories here are very good.  There''s a glaring inconsistency in the tableau - that bike is a very nice bike.  Makes you wonder how it got there, to whom it belongs, and why it is still there.  The processing is OK for this scene, though some may feel it too "slick" for a street scene (as in too Topaz''d, HDR''d, whatever).  Great variety of textures, good light.  All in all it works quite well for me.  You''ll note that your commenter average is VERY high - you hit a target audience, it seems.  Some days that is far better than mass appeal in my opinion.  I suspect from a DPC perspective, this didn''t have "in your face" enough parallel lines to truly meet the chalenge for some people.  I didn''t vote this challenge, but this is definitely right up my alley, so to speak.', '2010-03-10 13:03:30.000000', NULL, 0),
(5898617, 858142, 70503, '<td valign="top">Congrats on top 10! The reflection is awesome.</td>', 'Congrats on top 10! The reflection is awesome.', '2010-03-10 13:18:11.000000', NULL, 0),
