(5907115, 858212, 106233, '<td valign="top">Great perspective and composition!</td>', 'Great perspective and composition!', '2010-03-16 21:01:41.000000', NULL, 0),
(5911015, 856795, 108069, '<td valign="top">This photo is so well done. You placed one spot ahead of me and it''s laughable how much better this photo is. I played up the lines but you got some nice lines and excellent sharpness and surprising processing in basic. Great job. I''d be happy to follow you up any day.</td>', 'This photo is so well done. You placed one spot ahead of me and it''s laughable how much better this photo is. I played up the lines but you got some nice lines and excellent sharpness and surprising processing in basic. Great job. I''d be happy to follow you up any day.', '2010-03-20 10:42:06.000000', NULL, 0),
(5926175, 857450, 98339, '<td valign="top">I really like your prospective of this...I never think of looking up like that...need to do that more often...</td>', 'I really like your prospective of this...I never think of looking up like that...need to do that more often...', '2010-04-01 19:01:53.000000', NULL, 0),
(5937090, 858008, 7786, '<td valign="top">Congrats with an excellent image and also congrats with the 5D MK II and the new lens. Awesome piece of equipment.</td>', 'Congrats with an excellent image and also congrats with the 5D MK II and the new lens. Awesome piece of equipment.', '2010-04-08 06:12:18.000000', NULL, 0),
(5944129, 858187, 107453, '<td valign="top">Another excellent photograph. Love it.</td>', 'Another excellent photograph. Love it.', '2010-04-13 13:23:31.000000', NULL, 0),
